  void LoadModernSettings(){try{if(!File.Exists(extraFile))return;var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(extraFile));object v;if(d.TryGetValue("Prompts",out v))prompts.SelectedIndex=Convert.ToString(v)=="ps"?1:0;if(d.TryGetValue("Keyboard",out v))keyboard.Checked=Convert.ToBoolean(v);if(d.TryGetValue("Anisotropy",out v))anisotropy.SelectedIndex=Math.Max(0,Math.Min(5,Convert.ToInt32(v)));if(d.TryGetValue("Fsr",out v)){int n=Convert.ToInt32(v);if(n<fsrQuality.Items.Count)fsrQuality.SelectedIndex=n;}if(d.TryGetValue("FsrProfile",out v)){string profile=Convert.ToString(v);int mode=Array.IndexOf(new[]{"native","performance","balanced","quality"},profile);if(fsrQuality.Items.Count==3&&mode>=2)mode=2;fsrQuality.SelectedIndex=Math.Max(0,Math.Min(fsrQuality.Items.Count-1,mode));}foreach(var key in keyFields.Keys)if(d.TryGetValue(key,out v))keyFields[key].Text=Convert.ToString(v);}catch{}}
  void SaveModernSettings(){if(!modernReady)return;var d=new Dictionary<string,object>{{"Prompts",prompts.SelectedIndex==1?"ps":"xbox"},{"Keyboard",keyboard.Checked},{"Anisotropy",anisotropy.SelectedIndex},{"Fsr",fsrQuality.SelectedIndex},{"FsrProfile",SelectedFsrProfile()}};foreach(var p in keyFields)d[p.Key]=p.Value.Text;File.WriteAllText(extraFile,new JavaScriptSerializer().Serialize(d));}
